6	/// Sequence length used for conservative prefill scratch reservation.
7	///
8	/// This is not an admission cap. Actual prompt admission is governed by the
9	/// paged KV pool, RoPE cache coverage, and allocation success. Prompts longer
10	/// than this are handled by chunking prefill at `PREFILL_CHUNK_LEN` rather than
11	/// being rejected (see `prefill_last_hidden`).
12	pub(crate) const SCRATCH_ESTIMATE_SEQ: usize = 20_000;
13	
14	/// Maximum number of tokens processed in a single prefill forward pass.
15	///
16	/// Prefill is chunked at this granularity so the per-pass GDR scratch
17	/// (`GdrChunkwiseScratch35`, which scales linearly with the pass length) never
18	/// exceeds the memory reserved at startup. Kept equal to `SCRATCH_ESTIMATE_SEQ`
19	/// so the reservation in `weights.rs` covers exactly one chunk.
20	pub(crate) const PREFILL_CHUNK_LEN: usize = SCRATCH_ESTIMATE_SEQ;
21	const HEAD_DIM: usize = 256;
22	
