39	struct PrefillKvAccess<'a> {
40	    buffer: &'a cudarc::driver::CudaSlice<half::bf16>,
41	    layout: pegainfer_core::kv_pool::KvLayout,
42	    plan: &'a PrefillPagedPlan,
43	    base_pos: usize,
44	}
45	
46	fn checked_prefill_end_pos(
47	    base_pos: usize,
48	    seq_len: usize,
49	    max_position_embeddings: usize,
50	) -> Result<usize> {
51	    let end_pos = base_pos.checked_add(seq_len).ok_or_else(|| {
52	        anyhow::anyhow!("Qwen3.5 prefill position overflow: base_pos={base_pos}, seq_len={seq_len}")
53	    })?;
54	    anyhow::ensure!(
55	        end_pos <= max_position_embeddings,
56	        "Qwen3.5 prefill requested end_pos={end_pos}, beyond max_position_embeddings={max_position_embeddings}"
57	    );
58	    Ok(end_pos)
59	}
