61	impl Qwen35Model {
62	    pub(super) fn prefill_last_hidden(
63	        &self,
64	        token_ids: &[u32],
65	        full_view: &KvView,
66	        kv_buffer: &KvBuffer,
67	        recurrent: &mut RecurrentState,
68	    ) -> Result<DeviceVec> {
69	        anyhow::ensure!(
70	            !token_ids.is_empty(),
71	            "Qwen3.5 prefill requires at least one token"
72	        );
73	        // Validate the full target range up front (position overflow + RoPE cache
74	        // coverage) so an out-of-range prompt is rejected before any chunk mutates
75	        // the KV / recurrent state, rather than failing partway through.
76	        let base_pos = recurrent.seq_len;
77	        let end_pos = checked_prefill_end_pos(
78	            base_pos,
79	            token_ids.len(),
80	            self.config.max_position_embeddings,
81	        )?;
82	        anyhow::ensure!(
83	            full_view.seq_len() == end_pos,
84	            "Qwen3.5 prefill view ends at {}, expected {end_pos}",
85	            full_view.seq_len()
86	        );
87	        self.ensure_rope_cache_covers(end_pos)?;
88	
89	        // Run prefill in serial chunks of at most `PREFILL_CHUNK_LEN` tokens. Each
90	        // chunk advances the paged KV and linear-attention recurrent/conv state in
91	        // place, so the next chunk continues from the previous one. This caps the
92	        // per-pass GDR scratch (which grows with the pass length) at the budget
93	        // reserved at startup, so prompts longer than one chunk prefill without OOM.
94	        let page_size = kv_buffer.layout().page_size;
95	        let mut hidden_batch = None;
96	        let mut offset = 0usize;
97	        for chunk in token_ids.chunks(PREFILL_CHUNK_LEN) {
98	            // Free the previous chunk's hidden states before allocating the next
99	            // chunk's scratch so peak memory stays within one chunk's reservation.
100	            drop(hidden_batch.take());
101	            let (chunk_hidden, chunk_scratch) = self.prepare_prefill_chunk(chunk)?;
102	            let chunk_end = base_pos + offset + chunk.len();
103	            let page_count = chunk_end.div_ceil(page_size);
104	            let chunk_view = KvView::new(
105	                full_view.page_indices()[..page_count].to_vec(),
106	                chunk_end,
107	                page_size,
108	            );
109	            let page_indices = vec![chunk_view.page_indices().to_vec()];
110	            let plan = PrefillPagedPlan::from_raw_batch_with_cta_tile_q(
111	                &self.ctx,
112	                &page_indices,
113	                &[chunk_view.last_page_len()],
114	                &[base_pos + offset],
115	                &[chunk.len()],
116	                self.geometry.local_num_attention_heads(),
117	                self.geometry.local_num_key_value_heads(),
118	                self.config.head_dim,
119	                0,
120	            )?;
121	            let access = PrefillKvAccess {
122	                buffer: kv_buffer.buffer(),
123	                layout: pegainfer_core::kv_pool::KvLayout::new(
124	                    kv_buffer.layout().num_layers,
125	                    kv_buffer.layout().num_kv_heads,
126	                    kv_buffer.layout().head_dim,
127	                    page_size,
128	                )?,
129	                plan: &plan,
130	                base_pos: base_pos + offset,
131	            };
132	            hidden_batch = Some(self.prefill_chunk_forward(
133	                chunk_hidden,
134	                chunk_scratch,
135	                &access,
136	                recurrent,
137	            )?);
138	            offset += chunk.len();
139	        }
140	        // `seq_len > 0` guarantees at least one chunk produced hidden states.
141	        let hidden_batch = hidden_batch.expect("non-empty prefill produced no chunk");
142	
143	        // Last-token logic runs once, on the final chunk's output.
144	        ops::extract_vec(&self.ctx, &hidden_batch, hidden_batch.seq_len - 1)
145	    }
