147	    pub(super) fn batch_last_hidden_logits(
148	        &self,
149	        last_hiddens: &[DeviceVec],
150	    ) -> Result<HiddenStates> {
151	        let n = last_hiddens.len();
152	        anyhow::ensure!(n > 0, "batch_last_hidden_logits requires at least one row");
153	        let hidden_dim = self.config.hidden_size;
154	
155	        let mut batched = HiddenStates::zeros(&self.ctx, hidden_dim, n)?;
156	        for (request_idx, last_hidden) in last_hiddens.iter().enumerate() {
157	            anyhow::ensure!(
158	                last_hidden.len == hidden_dim,
159	                "Qwen3.5 last hidden row {request_idx} has len {}, expected {hidden_dim}",
160	                last_hidden.len
161	            );
162	            ops::write_vec_into(&self.ctx, last_hidden, &mut batched, request_idx)?;
163	        }
164	
165	        let mut normed = HiddenStates::zeros(&self.ctx, hidden_dim, n)?;
166	        ops::rms_norm_batch_offset_into(
167	            &self.ctx,
168	            &batched,
169	            &self.norm,
170	            self.config.rms_norm_eps,
171	            &mut normed,
172	        )?;
173	        let mut logits = HiddenStates::zeros(&self.ctx, self.config.selection_vocab, n)?;
174	        self.output_logits_into(&normed, &mut logits)?;
175	        debug_assert_eq!(logits.seq_len, n);
176	        Ok(logits)
177	    }
