179	    fn prepare_prefill_chunk(
180	        &self,
181	        token_ids: &[u32],
182	    ) -> Result<(HiddenStates, GdrChunkwiseScratch35)> {
183	        let seq_len = token_ids.len();
184	        let c = &self.config;
185	
186	        // Embeddings for this chunk.
187	        let token_ids_gpu = self
188	            .ctx
189	            .stream
190	            .clone_htod(token_ids)
191	            .map_err(|e| anyhow::anyhow!("H2D copy failed: {e}"))?;
192	        let mut hidden_batch = HiddenStates::zeros(&self.ctx, c.hidden_size, seq_len)?;
193	        ops::embedding_batch(
194	            &self.ctx,
195	            &self.embed_tokens,
196	            &token_ids_gpu,
197	            &mut hidden_batch,
198	        )?;
199	        let gdr_chunkwise_scratch =
200	            GdrChunkwiseScratch35::new(&self.ctx, c, self.geometry, seq_len)?;
201	        Ok((hidden_batch, gdr_chunkwise_scratch))
202	    }
203	
204	    fn prefill_chunk_forward(
205	        &self,
206	        mut hidden_batch: HiddenStates,
207	        mut gdr_chunkwise_scratch: GdrChunkwiseScratch35,
208	        kv: &PrefillKvAccess<'_>,
209	        recurrent: &mut RecurrentState,
210	    ) -> Result<HiddenStates> {
211	        let seq_len = hidden_batch.seq_len;
212	        // Process layers
213	        let mut linear_idx = 0usize;
214	        let mut full_idx = 0usize;
215	
216	        for (layer_idx, layer) in self.layers.iter().enumerate() {
217	            hidden_batch = self.prefill_layer(
218	                layer_idx,
219	                layer,
220	                &hidden_batch,
221	                &mut gdr_chunkwise_scratch,
222	                &mut linear_idx,
223	                &mut full_idx,
224	                kv,
225	                recurrent,
226	            )?;
227	        }
228	
229	        // Advance recurrent token count for the next chunk / decode step; the
230	        // paged KV position is committed by the caller.
231	        recurrent.seq_len += seq_len;
232	
233	        Ok(hidden_batch)
234	    }
