236	    /// Process one layer during prefill. Returns updated hidden_batch.
237	    #[allow(clippy::too_many_arguments)]
238	    fn prefill_layer(
239	        &self,
240	        _layer_idx: usize,
241	        layer: &TransformerBlock35,
242	        hidden_batch: &HiddenStates,
243	        gdr_chunkwise_scratch: &mut GdrChunkwiseScratch35,
244	        linear_idx: &mut usize,
245	        full_idx: &mut usize,
246	        kv: &PrefillKvAccess<'_>,
247	        recurrent: &mut RecurrentState,
248	    ) -> Result<HiddenStates> {
249	        let c = &self.config;
250	        let eps = c.rms_norm_eps;
251	        let seq_len = hidden_batch.seq_len;
252	
253	        // 1. Input layernorm — per-token (no batched offset norm kernel yet)
254	        // Use standard batched norm and add the offset correction manually
255	        // Actually we need the (1+w) variant. Process token by token for now.
256	        let mut normed_batch =
257	            self.batched_rms_norm_offset(hidden_batch, &layer.input_layernorm, eps)?;
258	
259	        // 2. Attention / Linear attention — per-token for correctness
260	        let geom = self.geometry;
261	        let attn_out_dim = match &layer.attn {
262	            LayerKind::FullAttention(_) => geom.local_full_attn_q_dim(),
263	            LayerKind::LinearAttention(_) => geom.local_linear_z_dim(),
264	        };
265	
266	        // Batch project, then per-token attention/recurrent
267	        let attn_results = match &layer.attn {
268	            LayerKind::FullAttention(attn) => self.prefill_full_attention(
269	                attn,
270	                &normed_batch,
271	                full_idx,
272	                kv,
273	                attn_out_dim,
274	                seq_len,
275	            )?,
276	            LayerKind::LinearAttention(attn) => self.prefill_linear_attention(
277	                attn,
278	                &normed_batch,
279	                linear_idx,
280	                recurrent,
281	                gdr_chunkwise_scratch,
282	                seq_len,
283	            )?,
284	        };
285	
286	        // 3. Residual + post-attention layernorm
287	        let hidden_plus_attn = ops::add_batch(&self.ctx, hidden_batch, &attn_results)?;
288	
289	        // Post-attention layernorm (1+weight offset, batched per-token)
290	        normed_batch =
291	            self.batched_rms_norm_offset(&hidden_plus_attn, &layer.post_attention_layernorm, eps)?;
292	
293	        // 4. MLP (batched)
294	        let gate_up_out = ops::gemm(&self.ctx, &layer.mlp.gate_up_proj, &normed_batch)?;
295	        let mut act_out = HiddenStates::zeros(&self.ctx, geom.local_intermediate_size(), seq_len)?;
296	        ops::silu_mul_fused_batch_into(&self.ctx, &gate_up_out, &mut act_out)?;
297	        let mut mlp_out = ops::gemm(&self.ctx, &layer.mlp.down_proj, &act_out)?;
298	        self.all_reduce_hidden(&mut mlp_out)?;
299	
300	        // 5. Residual
301	        ops::add_batch(&self.ctx, &hidden_plus_attn, &mlp_out)
302	    }
303	
304	    #[allow(clippy::too_many_arguments)]
305	    fn prefill_full_attention(
306	        &self,
307	        attn: &FullAttentionLayer,
308	        normed_batch: &HiddenStates,
309	        full_idx: &mut usize,
310	        kv: &PrefillKvAccess<'_>,
311	        _attn_out_dim: usize,
312	        seq_len: usize,
313	    ) -> Result<HiddenStates> {
314	        let c = &self.config;
315	        let geom = self.geometry;
316	        let num_attention_heads = geom.local_num_attention_heads();
317	        let num_key_value_heads = geom.local_num_key_value_heads();
318	        let attn_out_dim = geom.local_full_attn_q_dim();
319	        let eps = c.rms_norm_eps;
320	        let q_full_batch = ops::gemm(&self.ctx, &attn.q_proj, normed_batch)?;
321	        let k_batch = ops::gemm(&self.ctx, &attn.k_proj, normed_batch)?;
322	        let v_batch = ops::gemm(&self.ctx, &attn.v_proj, normed_batch)?;
323	        let mut attn_out_batch = HiddenStates::zeros(&self.ctx, attn_out_dim, seq_len)?;
324	
325	        let base_pos = kv.base_pos;
326	        let mut q_prepped = HiddenStates::zeros(&self.ctx, attn_out_dim, seq_len)?;
327	        let start_pos_cpu: CudaSlice<i32> = self
328	            .ctx
329	            .stream
330	            .clone_htod(&[base_pos as i32])
331	            .map_err(|e| anyhow::anyhow!("H2D start_pos failed: {e}"))?;
332	        let layout = &kv.layout;
333	        let layer_k_off = (*full_idx * layout.layer_stride) as i64;
334	        let layer_v_off = layer_k_off + layout.kv_block_len as i64;
335	        let stride_page = layout.page_stride as i64;
336	
337	        // Step 1: QK norm + partial RoPE + direct paged K/V write.
338	        unsafe {
339	            let (qf_ptr, _) = q_full_batch.data.device_ptr(&self.ctx.stream);
340	            let (k_ptr, _) = k_batch.data.device_ptr(&self.ctx.stream);
341	            let (v_ptr, _) = v_batch.data.device_ptr(&self.ctx.stream);
342	            let (qn_ptr, _) = attn.q_norm.data.device_ptr(&self.ctx.stream);
343	            let (kn_ptr, _) = attn.k_norm.data.device_ptr(&self.ctx.stream);
344	            let (cos_ptr, _) = self.cos_cache.data.device_ptr(&self.ctx.stream);
345	            let (sin_ptr, _) = self.sin_cache.data.device_ptr(&self.ctx.stream);
346	            let (qp_ptr, _) = q_prepped.data.device_ptr_mut(&self.ctx.stream);
347	            let (buf_ptr, _) = kv.buffer.device_ptr(&self.ctx.stream);
348	            let (pi_ptr, _) = kv.plan.page_indices_d().device_ptr(&self.ctx.stream);
349	            let (sp_ptr, _) = start_pos_cpu.device_ptr(&self.ctx.stream);
350	            ffi::prefill_attention_hd256_prep_paged_cuda(
351	                qf_ptr as *const ffi::Half,
352	                k_ptr as *const ffi::Half,
353	                v_ptr as *const ffi::Half,
354	                qn_ptr as *const ffi::Half,
355	                kn_ptr as *const ffi::Half,
356	                cos_ptr as *const ffi::Half,
357	                sin_ptr as *const ffi::Half,
358	                qp_ptr as *mut ffi::Half,
359	                buf_ptr as *mut ffi::Half,
360	                layer_k_off,
361	                layer_v_off,
362	                pi_ptr as *const i32,
363	                num_attention_heads as i32,
364	                num_key_value_heads as i32,
365	                seq_len as i32,
366	                sp_ptr as *const i32,
367	                c.rotary_dim as i32,
368	                eps,
369	                layout.page_size as i32,
370	                stride_page,
371	                self.ctx.stream.cu_stream(),
372	            );
373	        }
374	
375	        // Step 2: Batch prefill paged attention (HD=256).
376	        let sm_scale = 1.0f32 / f32::sqrt(HEAD_DIM as f32);
377	        {
378	            let (buf_ptr, _gbuf) = kv.buffer.device_ptr(&self.ctx.stream);
379	            let (qp_ptr, _gqp) = q_prepped.data.device_ptr(&self.ctx.stream);
380	            let (out_ptr, _go) = attn_out_batch.data.device_ptr_mut(&self.ctx.stream);
381	            let (pi_ptr, _gpi) = kv.plan.page_indices_d().device_ptr(&self.ctx.stream);
382	            let (pip_ptr, _gpip) = kv.plan.page_indptr_d().device_ptr(&self.ctx.stream);
383	            let (lpl_ptr, _glpl) = kv.plan.last_page_len_d().device_ptr(&self.ctx.stream);
384	            let (qi_ptr, _gqi) = kv.plan.q_indptr_d().device_ptr(&self.ctx.stream);
385	            let (ri_ptr, _gri) = kv.plan.request_indices_d().device_ptr(&self.ctx.stream);
386	            let (qti_ptr, _gqti) = kv.plan.qo_tile_indices_d().device_ptr(&self.ctx.stream);
387	            let (kti_ptr, _gkti) = kv.plan.kv_tile_indices_d().device_ptr(&self.ctx.stream);
388	            let (kcs_ptr, _gkcs) = kv.plan.kv_chunk_size_d().device_ptr(&self.ctx.stream);
389	            let (tnr_ptr, _gtnr) = kv.plan.total_num_rows_d().device_ptr(&self.ctx.stream);
390	            let result = unsafe {
391	                ffi::batch_prefill_paged_cuda_hd256(
392	                    qp_ptr as *const ffi::Half,
393	                    out_ptr as *mut ffi::Half,
394	                    buf_ptr as *const ffi::Half,
395	                    layer_k_off,
396	                    layer_v_off,
397	                    pi_ptr as *const i32,
398	                    pip_ptr as *const i32,
399	                    lpl_ptr as *const i32,
400	                    qi_ptr as *const i32,
401	                    ri_ptr as *const i32,
402	                    qti_ptr as *const i32,
403	                    kti_ptr as *const i32,
404	                    kcs_ptr as *const i32,
405	                    tnr_ptr as *const u32,
406	                    num_attention_heads as i32,
407	                    num_key_value_heads as i32,
408	                    HEAD_DIM as i32,
409	                    layout.page_size as i32,
410	                    seq_len as i32,
411	                    kv.plan.batch_size(),
412	                    kv.plan.num_tiles(),
413	                    stride_page,
414	                    sm_scale,
415	                    self.ctx.stream.cu_stream(),
416	                )
417	            };
418	            anyhow::ensure!(
419	                result == 0,
420	                "batch_prefill_paged_cuda_hd256 failed: {result}{}",
421	                pegainfer_kernels::ops::ffi_exception_message(result)
422	            );
423	        }
424	
425	        // Step 3: Apply gate from q_full_batch.
426	        {
427	            let (qf_ptr, _gqf) = q_full_batch.data.device_ptr(&self.ctx.stream);
428	            let (out_ptr, _go) = attn_out_batch.data.device_ptr_mut(&self.ctx.stream);
429	            unsafe {
430	                ffi::attention_gate_batch_hd256_cuda(
431	                    qf_ptr as *const ffi::Half,
432	                    out_ptr as *mut ffi::Half,
433	                    num_attention_heads as i32,
434	                    seq_len as i32,
435	                    self.ctx.stream.cu_stream(),
436	                );
437	            }
438	        }
439	
440	        *full_idx += 1;
441	
442	        // O projection (batched)
443	        let mut projected = ops::gemm(&self.ctx, &attn.o_proj, &attn_out_batch)?;
444	        self.all_reduce_hidden(&mut projected)?;
445	        Ok(projected)
446	    }
447	
448	    fn prefill_linear_attention(
449	        &self,
450	        attn: &LinearAttentionLayer,
451	        normed_batch: &HiddenStates,
452	        linear_idx: &mut usize,
453	        recurrent: &mut RecurrentState,
454	        gdr_chunkwise_scratch: &mut GdrChunkwiseScratch35,
455	        seq_len: usize,
456	    ) -> Result<HiddenStates> {
457	        let c = &self.config;
458	        let geom = self.geometry;
459	
460	        // Batch projections. The weights are the fused ones the decode path
461	        // issues a single GEMM against; a prefill step reads the row range it
462	        // wants into its own buffer, so every kernel downstream is unchanged.
463	        let qkv_dim = geom.local_linear_qkv_dim();
464	        let z_dim = geom.local_linear_z_dim();
465	        let value_heads = geom.local_linear_num_value_heads();
466	
467	        let mut qkv_batch = HiddenStates::zeros(&self.ctx, qkv_dim, seq_len)?;
468	        ops::gemm_rows_into(
469	            &self.ctx,
470	            &attn.in_proj_qkvz,
471	            0,
472	            qkv_dim,
473	            normed_batch,
474	            &mut qkv_batch,
475	        );
476	        let mut z_batch = HiddenStates::zeros(&self.ctx, z_dim, seq_len)?;
477	        ops::gemm_rows_into(
478	            &self.ctx,
479	            &attn.in_proj_qkvz,
480	            qkv_dim,
481	            z_dim,
482	            normed_batch,
483	            &mut z_batch,
484	        );
485	        let mut b_batch = HiddenStates::zeros(&self.ctx, value_heads, seq_len)?;
486	        ops::gemm_rows_into(
487	            &self.ctx,
488	            &attn.in_proj_ba,
489	            0,
490	            value_heads,
491	            normed_batch,
492	            &mut b_batch,
493	        );
494	        let mut a_batch = HiddenStates::zeros(&self.ctx, value_heads, seq_len)?;
495	        ops::gemm_rows_into(
496	            &self.ctx,
497	            &attn.in_proj_ba,
498	            value_heads,
499	            value_heads,
500	            normed_batch,
501	            &mut a_batch,
502	        );
503	
504	        let layer_state = &mut recurrent.layers[*linear_idx];
505	
506	        let mut qkv_conv_batch = HiddenStates::zeros(&self.ctx, qkv_dim, seq_len)?;
507	        ops::conv1d_prefill_batch_into(
508	            &self.ctx,
509	            &qkv_batch,
510	            &attn.conv1d_weight,
511	            &mut layer_state.conv_state,
512	            &mut qkv_conv_batch,
513	            c.linear_conv_kernel_dim,
514	        );
515	
516	        let mut gdr_out_batch = HiddenStates::zeros(&self.ctx, z_dim, seq_len)?;
517	        ops::gated_delta_rule_prefill_chunkwise_into(
518	            &self.ctx,
519	            &qkv_conv_batch,
520	            &b_batch,
521	            &a_batch,
522	            &attn.dt_bias,
523	            &attn.a_log,
524	            &mut layer_state.state,
525	            gdr_chunkwise_scratch,
526	            &mut gdr_out_batch,
527	            geom.local_linear_num_key_heads(),
528	            geom.local_linear_num_value_heads(),
529	            c.linear_key_head_dim,
530	            c.linear_value_head_dim,
531	        )?;
532	
533	        let mut normed_out_batch = HiddenStates::zeros(&self.ctx, z_dim, seq_len)?;
534	        ops::rms_norm_gated_batch_into(
535	            &self.ctx,
536	            &gdr_out_batch,
537	            &attn.norm_weight,
538	            &z_batch,
539	            &mut normed_out_batch,
540	            geom.local_linear_num_value_heads(),
541	            c.linear_value_head_dim,
542	            c.rms_norm_eps,
543	            ops::GatedNormActivation::Silu,
544	        );
545	
546	        *linear_idx += 1;
547	
548	        // Output projection (batched)
549	        let mut projected = ops::gemm(&self.ctx, &attn.out_proj, &normed_out_batch)?;
550	        self.all_reduce_hidden(&mut projected)?;
551	        Ok(projected)
552	    }
553	
554	    fn batched_rms_norm_offset(
555	        &self,
556	        x: &HiddenStates,
557	        weight: &DeviceVec,
558	        eps: f32,
559	    ) -> Result<HiddenStates> {
560	        let mut out = HiddenStates::zeros(&self.ctx, x.hidden_dim, x.seq_len)?;
561	        ops::rms_norm_batch_offset_into(&self.ctx, x, weight, eps, &mut out)?;
562	        Ok(out)
563	    }
564	}
565	
566	#[cfg(test)]
567	mod tests {
568	    use super::checked_prefill_end_pos;
569	
570	    #[test]
571	    fn checked_prefill_end_pos_accepts_config_limit() {
572	        assert_eq!(
573	            checked_prefill_end_pos(0, 262_144, 262_144).unwrap(),
574	            262_144
575	        );
576	        assert_eq!(
577	            checked_prefill_end_pos(262_143, 1, 262_144).unwrap(),
578	            262_144
579	        );
580	    }
