583	    fn checked_prefill_end_pos_rejects_past_config_limit() {
584	        let err = checked_prefill_end_pos(0, 262_145, 262_144)
585	            .unwrap_err()
586	            .to_string();
587	        assert!(err.contains("beyond max_position_embeddings=262144"));
588	        assert!(err.contains("requested end_pos=262145"));
589	    }
