204	    fn prefill_chunk_forward(
205	        &self,
206	        mut hidden_batch: HiddenStates,
207	        mut gdr_chunkwise_scratch: GdrChunkwiseScratch35,
208	        kv: &PrefillKvAccess<'_>,
209	        recurrent: &mut RecurrentState,
210	    ) -> Result<HiddenStates> {
211	        let seq_len = hidden_batch.seq_len;
212	        // Process layers
213	        let mut linear_idx = 0usize;
