1	//! Scheduler step drivers: batch prefill, overlap launch, unified
2	//! prefill+decode, pure decode, token dispatch/retirement, and the
3	//! chunked-prefill vocabulary shared with the backend.
4	
5	use super::*;
6	
7	// ── Batch prefill ───────────────────────────────────────────────────────
8	
9	pub(super) fn prefill_batch(
10	    backend: &mut SchedulerBackend,
11	    active: &mut Vec<ActiveRequest35>,
12	    scheduled: Vec<PrefillingRequest35>,
13	    prefilling: &mut Vec<PrefillingRequest35>,
14	    rng: &mut StdRng,
15	    ledger: &mut RequestLedger,
16	) -> Result<()> {
17	    let mut chunk = ScheduledChunk::from(scheduled);
18	    let sample_seed = rand::RngExt::random(rng);
19	    let artifacts = match backend {
20	        SchedulerBackend::Single(single) => {
21	            // Scope the borrows of `chunk` to the executor call so the error path can
22	            // move `chunk` into `fail_chunk`.
23	            let logits = match single.batch_prefill_logits(&mut chunk) {
24	                Ok(v) => v,
25	                Err(e) => {
26	                    warn!("batch prefill failed: {e}");
27	                    fail_chunk(chunk, &e.to_string(), ledger);
28	                    return Ok(());
29	                }
